package app.forgettime.audio;
import java.util.ArrayList;
/** Experimental review-only mel-flux-v1. No live detector integration. */
public final class MelDetector {
 public static final String VERSION="mel-flux-v1";
 public static final class Settings {
  public final int windowMs,bands,neighbor,confirmation;public final boolean rearming;public final double threshold;
  public Settings(){this(20,48,5,1,true,2);}
  public Settings(int w,int b,int n,int c,boolean r,double k){if((w!=10&&w!=20&&w!=40)||(b!=24&&b!=48&&b!=96)||(n!=1&&n!=3&&n!=5)||c<0||c>2||!Double.isFinite(k)||k<.5||k>4)throw new IllegalArgumentException("Invalid mel settings");windowMs=w;bands=b;neighbor=n;confirmation=c;rearming=r;threshold=k;}
 }
 public static final class Onset {public final double sourceFrame,flux,threshold;public final long analyzedThroughFrame;Onset(double f,long t,double x,double k){sourceFrame=f;analyzedThroughFrame=t;flux=x;threshold=k;}}
 public static final class Row {public final double center,flux,threshold;public final long through;public final boolean ready;Row(double c,long t,double f,double k,boolean r){center=c;through=t;flux=f;threshold=k;ready=r;}}
 private final Settings settings;private int rate=0,n=0,hop=0,historyLimit=0,cursor=0;private long first=0,expected=-1,seen=0,watermark=0;
 private double[] pcm=new double[0],window=new double[0],real=new double[0],imaginary=new double[0],cosine=new double[0],sine=new double[0],power=new double[0],previous=null,bands=new double[0];private double norm=0,last=Double.NEGATIVE_INFINITY;private boolean armed=true;
 private int[][] bins=new int[0][];private double[][] weights=new double[0][];private final ArrayList<Double> history=new ArrayList<>();private final ArrayList<Row> rows=new ArrayList<>();
 public MelDetector(){this(new Settings());}public MelDetector(Settings s){if(s==null)throw new IllegalArgumentException("Missing settings");settings=s;}
 public void reset(){n=0;hop=0;first=0;cursor=0;historyLimit=0;pcm=new double[0];window=new double[0];real=new double[0];imaginary=new double[0];cosine=new double[0];sine=new double[0];power=new double[0];bands=new double[0];bins=new int[0][];weights=new double[0][];rate=0;expected=-1;seen=0;previous=null;history.clear();rows.clear();armed=true;last=Double.NEGATIVE_INFINITY;watermark=0;}
 private static double mel(double f){return f<1000?f/(200.0/3):15+Math.log(f/1000)/(Math.log(6.4)/27);}
 private static double hz(double m){return m<15?m*(200.0/3):1000*Math.exp((m-15)*(Math.log(6.4)/27));}
 private void configure(int r,long start){reset();rate=r;first=start;expected=start;watermark=start;n=Math.max(128,Math.min(8192,(int)Math.pow(2,Math.round(Math.log(r*settings.windowMs/1000.0)/Math.log(2)))));hop=Math.max(1,(int)Math.round(r*.0025));historyLimit=(int)Math.ceil(r*.1/hop);cursor=0;
  pcm=new double[n];window=new double[n];real=new double[n];imaginary=new double[n];power=new double[n/2+1];cosine=new double[n/2];sine=new double[n/2];double sum=0;for(int i=0;i<n;i++){window[i]=.5-.5*Math.cos(2*Math.PI*i/(n-1));sum+=window[i];}norm=sum*sum;for(int i=0;i<n/2;i++){cosine[i]=Math.cos(-2*Math.PI*i/n);sine[i]=Math.sin(-2*Math.PI*i/n);}
  double[] edges=new double[settings.bands+2];for(int i=0;i<edges.length;i++)edges[i]=hz(mel(30)+(mel(Math.min(16000,r/2.0))-mel(30))*i/(settings.bands+1));
  bins=new int[settings.bands][];weights=new double[settings.bands][];for(int b=0;b<settings.bands;b++){ArrayList<Integer> bi=new ArrayList<>();ArrayList<Double> we=new ArrayList<>();for(int j=0;j<=n/2;j++){double f=j*r/(double)n,w=Math.max(0,Math.min((f-edges[b])/(edges[b+1]-edges[b]),(edges[b+2]-f)/(edges[b+2]-edges[b+1])))*2/(edges[b+2]-edges[b]);if(w>0){bi.add(j);we.add(w);}}if(bi.isEmpty()){reset();throw new IllegalArgumentException("Mel filter has no spectral bins at this rate/window");}bins[b]=new int[bi.size()];weights[b]=new double[we.size()];for(int i=0;i<bi.size();i++){bins[b][i]=bi.get(i);weights[b][i]=we.get(i);}}bands=new double[settings.bands];
 }
 public Onset process(float sample,long frame,int sampleRate){if(!Float.isFinite(sample)||frame<0||frame>=9007199254740991L||sampleRate<8000||sampleRate>192000)throw new IllegalArgumentException("Invalid mel PCM clock or sample");if(rate!=sampleRate||expected!=frame)configure(sampleRate,frame);expected=frame+1;pcm[cursor]=sample;cursor=(cursor+1)%n;seen++;if(seen<n||(seen-n)%hop!=0)return null;
  for(int i=0;i<n;i++){real[i]=pcm[(cursor+i)%n]*window[i];imaginary[i]=0;}fft();for(int j=0;j<power.length;j++)power[j]=(real[j]*real[j]+imaginary[j]*imaginary[j])/norm;
  double flux=0;for(int b=0;b<settings.bands;b++){double energy=0;for(int j=0;j<bins[b].length;j++)energy+=weights[b][j]*power[bins[b][j]];double value=Math.log1p(energy/1e-8);bands[b]=value;if(previous!=null){double reference=0;int half=settings.neighbor/2;for(int k=Math.max(0,b-half);k<=Math.min(settings.bands-1,b+half);k++)reference=Math.max(reference,previous[k]);flux+=Math.max(0,value-reference);}}flux/=settings.bands;previous=bands.clone();double mean=0,variance=0;for(double v:history)mean+=v;mean/=Math.max(1,history.size());for(double v:history)variance+=(v-mean)*(v-mean);variance/=Math.max(1,history.size());Row row=new Row(frame-n+1+(n-1)/2.0,frame+1,flux,mean+settings.threshold*Math.sqrt(variance)+.005,history.size()==historyLimit);
  history.add(flux);if(history.size()>historyLimit)history.remove(0);rows.add(row);if(rows.size()>settings.confirmation+2)rows.remove(0);watermark=Math.max(first,(long)Math.floor(row.center+(1-settings.confirmation)*hop));int index=rows.size()-1-settings.confirmation;if(index<1)return null;Row candidate=rows.get(index);if(candidate.ready&&candidate.flux<=candidate.threshold)armed=true;boolean maximum=true;for(int j=index+1;j<rows.size();j++)if(candidate.flux<=rows.get(j).flux)maximum=false;
  if(candidate.ready&&(!settings.rearming||armed)&&candidate.flux>candidate.threshold&&candidate.flux>rows.get(index-1).flux&&maximum&&candidate.center-last>=rate*.018){last=candidate.center;armed=false;return new Onset(candidate.center,row.through,candidate.flux,candidate.threshold);}return null;
 }
 private void fft(){for(int i=1,j=0;i<n;i++){int bit=n>>1;for(;(j&bit)!=0;bit>>=1)j^=bit;j^=bit;if(i<j){double t=real[i];real[i]=real[j];real[j]=t;}}for(int length=2;length<=n;length*=2)for(int base=0;base<n;base+=length)for(int j=0;j<length/2;j++){int at=j*n/length,u=base+j,v=u+length/2;double c=cosine[at],s=sine[at],tr=real[v]*c-imaginary[v]*s,ti=real[v]*s+imaginary[v]*c;real[v]=real[u]-tr;imaginary[v]=imaginary[u]-ti;real[u]+=tr;imaginary[u]+=ti;}}
 public double[] power(){return power.clone();}public double[] logMel(){return bands.clone();}public Row latest(){return rows.isEmpty()?null:rows.get(rows.size()-1);}public int windowFrames(){return n;}public int hopFrames(){return hop;}public long processedThroughFrame(){return watermark;}public long reliableFromFrame(){return rate==0?0:(long)Math.floor(first+(n-1)/2.0+historyLimit*hop);}public long receivedThroughFrame(){return Math.max(0,expected);}
}
